template <bool isNzToNZ, typename T>
__aicore__ inline void AscendCMLAPreprocessMixBF16<T>::ProcessRawQ(
    uint32_t startHead, uint32_t headBlockLen, uint32_t loopN,
    uint64_t qOffset, uint64_t outLineOffset) {
    AscendC::LocalTensor<T> inputQ = this->inputQ_.Get(
        inLocalTensorOffset, {loopN * headBlockLen * this->qkNopeHeadDim_});

    // DataCopy from global to local for Q
    AscendC::DataCopy(inputQ, this->qGm_[qOffset],
                      {loopN, headBlockLen, static_cast<uint16_t>(qkNopeHeadDim_ / 16), 0});
    // 经 V 单元中转：冗余，因为 ProcessRawQ 无 V 指令
    SET_FLAG(MTE2, V, EVENT_ID1);
    WAIT_FLAG(MTE2, V, EVENT_ID1);

    // 标量计算在等待之后串行执行
    uint64_t outQOffset = startHead * outLineOffset + this->concatSize;
    uint64_t outQOffset2 = startHead * this->headDim;
    SET_FLAG(V, MTE3, EVENT_ID1);
    WAIT_FLAG(V, MTE3, EVENT_ID1);

    // DataCopy from local to global for output Q
    AscendC::DataCopy(this->outQGm_[outQOffset], inputQ,
                      {loopN, headBlockLen, static_cast<uint16_t>(qkNopeHeadDim_ / 16), 0});
}

